<link rel="icon" href="<?= base_url('img/favicon.ico'); ?>"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@3.34.1/dist/tabler-icons.min.css"><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
*{box-sizing:border-box}body{margin:0;min-height:100vh;color:#132c4b;font-family:'Plus Jakarta Sans',sans-serif;background:radial-gradient(circle at 8% 0,#ffdc89 0,transparent 25rem),radial-gradient(circle at 95% 5%,#91e5e3 0,transparent 26rem),#f4f9fc}.scene-city{background:radial-gradient(circle at 9% 5%,#ffe19d 0,transparent 26rem),radial-gradient(circle at 95% 20%,#ffae85 0,transparent 28rem),#fff8ed}.top{max-width:960px;margin:auto;padding:19px 18px;display:flex;align-items:center;justify-content:space-between}.top a{font-size:.8rem;font-weight:800;text-decoration:none;color:#26627c}.mark{font-size:.72rem;letter-spacing:.1em;font-weight:900;color:#08766f}.shell{max-width:760px;margin:11px auto 0;padding:0 18px 64px}.progress{height:8px;background:#dfeef2;border-radius:999px;overflow:hidden;margin-bottom:18px}.progress b{display:block;height:100%;width:calc(100% / <?= max(1, (int) $total); ?>);border-radius:inherit;background:linear-gradient(90deg,<?= html_escape($level['color']); ?>,#2cb8a8);transition:width .35s}.meta{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:14px;font-size:.74rem;color:#577187}.meta strong{color:#0b6982}.mission-stage{position:relative;height:137px;margin-bottom:13px;padding:19px 24px;overflow:hidden;border-radius:23px;background:linear-gradient(122deg,#0e807d,#0a5b85);color:#fff;box-shadow:0 16px 33px #0c496222}.mission-stage.city{background:linear-gradient(122deg,#c85f51,#f38b59 62%,#f6b248)}.mission-stage:before{content:'';position:absolute;width:280px;height:280px;border:1px solid #ffffff3d;border-radius:50%;right:-128px;top:-172px;box-shadow:0 0 0 32px #ffffff13}.mission-stage small{position:relative;display:block;color:#d8fffb;font-size:.61rem;letter-spacing:.13em;font-weight:900}.mission-stage h2{position:relative;margin:6px 0 5px;font-size:1.2rem;letter-spacing:-.04em}.mission-stage p{position:relative;max-width:400px;margin:0;color:#e1ffff;font-size:.72rem;line-height:1.45}.scene-object{position:absolute;z-index:2;font-size:2rem;filter:drop-shadow(0 7px 4px #083e5638);animation:float 3.4s ease-in-out infinite}.scene-object.o1{right:28px;bottom:19px}.scene-object.o2{right:93px;top:23px;font-size:1.45rem;animation-delay:-1.1s}.scene-object.o3{right:148px;bottom:20px;font-size:1.35rem;animation-delay:-.5s}.scene-object.o4{right:204px;top:17px;font-size:1.15rem;animation-delay:-1.8s}.board{background:#fff;border:1px solid #dbeaf0;border-radius:28px;padding:clamp(22px,5vw,43px);box-shadow:0 22px 60px #0c35531c;position:relative;overflow:hidden}.board:before{content:'';width:260px;height:260px;border-radius:50%;position:absolute;right:-145px;top:-158px;background:<?= html_escape($level['color']); ?>;opacity:.09}.eyebrow{position:relative;display:inline-flex;align-items:center;gap:7px;color:#137a78;font-size:.68rem;letter-spacing:.11em;font-weight:900}.eyebrow i{color:#f3a31b;font-size:1rem}.question{position:relative;font-size:clamp(1.5rem,4vw,2.1rem);letter-spacing:-.05em;line-height:1.3;margin:18px 0 27px;max-width:600px}.options{display:grid;grid-template-columns:1fr 1fr;gap:11px}.option{border:1px solid #dce9ef;background:#fff;border-radius:15px;padding:15px 16px;display:flex;align-items:center;gap:11px;text-align:left;cursor:pointer;font:700 .91rem 'Plus Jakarta Sans',sans-serif;color:#183653;transition:.18s}.option:hover:not(:disabled),.option:focus-visible{border-color:<?= html_escape($level['color']); ?>;background:#f4fbfb;transform:translateY(-1px)}.option:disabled{cursor:default}.letter{display:grid;place-items:center;width:27px;height:27px;border-radius:9px;background:#edf4f7;color:#567089;font-size:.73rem;font-weight:900;flex:none}.scene-city .options{grid-template-columns:repeat(4,1fr);gap:9px;padding:7px 3px 17px;background:linear-gradient(90deg,#fff3e5,#fffaf2);border-radius:22px}.scene-city .option{min-height:104px;padding:11px 7px;flex-direction:column;justify-content:center;text-align:center;gap:7px;border-radius:19px;border-bottom-width:5px;background:#fffdfb}.scene-city .option:nth-child(2n){transform:translateY(13px)}.scene-city .option:hover:not(:disabled){transform:translateY(-4px) rotate(-1deg)}.scene-city .option:nth-child(2n):hover:not(:disabled){transform:translateY(7px) rotate(1deg)}.scene-city .letter{width:31px;height:31px;border-radius:50%;background:#ffe3b7;color:#aa5a3e}.scene-city .option.correct,.scene-city .option.wrong{transform:translateY(0)!important}.option.correct{background:#edfbf3;border-color:#35bf79;color:#087747}.option.correct .letter{background:#35bf79;color:#fff}.option.wrong{background:#fff0f0;border-color:#f18484;color:#aa3333}.option.wrong .letter{background:#ef6262;color:#fff}.hint-area{margin-top:20px;border-top:1px dashed #d9e6ec;padding-top:17px}.hint-actions{display:flex;gap:9px;flex-wrap:wrap}.hint-btn{border:1px solid #cbdfe7;background:#f8fcfd;color:#26627c;border-radius:10px;padding:9px 11px;font:800 .74rem 'Plus Jakarta Sans',sans-serif;cursor:pointer}.hint-btn:hover{background:#edf9f7}.hint{display:none;margin-top:11px;padding:12px 14px;border-radius:12px;background:#fff9e9;color:#876114;font-size:.8rem;line-height:1.55}.hint.show{display:block}.feedback{display:none;margin-top:20px;border-radius:18px;padding:17px 18px}.feedback.show{display:block}.feedback.good{background:#ecfbf2;border:1px solid #bcebd1}.feedback.bad{background:#fff4f2;border:1px solid #ffd0ca}.feedback h3{margin:0 0 5px;font-size:1rem}.feedback p{margin:0;color:#4b6577;font-size:.82rem;line-height:1.58}.tip{margin-top:10px;padding-top:10px;border-top:1px dashed #b9dccc;color:#19705e!important}.next{margin-top:14px;border:none;border-radius:12px;padding:12px 16px;background:linear-gradient(135deg,<?= html_escape($level['color']); ?>,#168f87);color:#fff;font:900 .82rem 'Plus Jakarta Sans',sans-serif;cursor:pointer;box-shadow:0 9px 18px #087f6930}.next:hover{opacity:.93}.result{display:none;text-align:center}.result.show{display:block}.result-badge{width:77px;height:77px;display:grid;place-items:center;margin:0 auto 15px;border-radius:26px;background:#eafaf4;color:#109663;font-size:2.3rem}.result h2{letter-spacing:-.055em;margin:0 0 8px;font-size:2rem}.result p{color:#5c7487;line-height:1.6;font-size:.88rem}.score{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:22px 0}.score div{border:1px solid #dcebef;background:#f9fcfd;border-radius:14px;padding:13px}.score b{display:block;font-size:1.3rem;color:#0b7181}.score small{font-size:.66rem;text-transform:uppercase;font-weight:800;letter-spacing:.06em;color:#6f8494}.result a{display:inline-block;margin-top:5px;text-decoration:none;border-radius:12px;padding:13px 19px;background:#087a80;color:#fff;font-size:.82rem;font-weight:900}.loading{opacity:.58;pointer-events:none}.celebrate .mission-stage{animation:mission-pop .55s ease}.celebrate .scene-object{animation:celebrate 700ms ease-in-out 2}@keyframes float{50%{transform:translateY(-8px) rotate(4deg)}}@keyframes celebrate{50%{transform:translateY(-19px) rotate(18deg) scale(1.25)}}@keyframes mission-pop{50%{transform:scale(1.015)}}@media(max-width:540px){.top{padding-top:14px}.mark{display:none}.shell{padding:0 12px 40px}.mission-stage{height:132px;padding:17px}.mission-stage p{max-width:240px}.scene-object.o4{display:none}.board{border-radius:22px;padding:24px 19px}.options,.scene-city .options{grid-template-columns:1fr}.scene-city .option{min-height:auto;flex-direction:row;text-align:left;padding:13px}.scene-city .option:nth-child(2n){transform:none}.question{margin:14px 0 21px}.option{padding:13px}.score{gap:6px}.score div{padding:11px 5px}}
</style><style>.scene-forest{background:radial-gradient(circle at 10% 4%,#d8f5a5 0,transparent 26rem),radial-gradient(circle at 95% 16%,#91e2ba 0,transparent 27rem),#f3fbef}.mission-stage.forest{background:linear-gradient(122deg,#1a704e,#289b69 58%,#64b464)}.scene-forest .options{padding:7px;background:linear-gradient(135deg,#edfae4,#f8fff5);border-radius:23px}.scene-forest .option{border-radius:18px;border-bottom-width:5px}.scene-forest .option:nth-child(1),.scene-forest .option:nth-child(4){transform:rotate(-1deg)}.scene-forest .option:nth-child(2),.scene-forest .option:nth-child(3){transform:rotate(1deg)}.scene-forest .option:hover:not(:disabled){transform:translateY(-4px) rotate(0)}.scene-forest .letter{background:#d9f1cb;color:#297548}@media(max-width:540px){.scene-forest .option:nth-child(n){transform:none}}</style></head><body class="scene-<?= html_escape($experience['scene']); ?>">
<header class="top"><a href="<?= base_url('belajar/matematika'); ?>"><i class="ti ti-arrow-left"></i> Peta Level</a><b class="mark"><i class="ti ti-map-2"></i> MATH EXPEDITION</b></header>
<main class="shell"><div class="progress"><b id="progress"></b></div><div class="meta"><span><strong><?= html_escape($experience['chapter_title']); ?></strong> · <?= html_escape($level['title']); ?></span><span id="counter">1 / <?= (int) $total; ?></span></div>
<section class="mission-stage <?= html_escape($experience['scene']); ?>"><small><?= html_escape($experience['chapter_title']); ?></small><h2><?= html_escape($experience['mission']); ?></h2><p><?= html_escape($experience['story']); ?></p><?php foreach($experience['objects'] as $index=>$object): ?><span class="scene-object o<?= $index+1; ?>"><?= html_escape($object); ?></span><?php endforeach; ?></section>
<section class="board" id="board"><div id="gamePanel"><span class="eyebrow"><i class="ti ti-sparkles"></i> JAWAB DENGAN TENANG</span><h1 class="question" id="prompt"></h1><div class="options" id="options"></div><div class="hint-area"><div class="hint-actions"><button class="hint-btn" id="hintOne"><i class="ti ti-bulb"></i> Petunjuk</button><button class="hint-btn" id="hintTwo"><i class="ti ti-compass"></i> Arah yang lebih jelas</button></div><div id="hintOneText" class="hint"></div><div id="hintTwoText" class="hint"></div></div><div class="feedback" id="feedback"></div></div><div class="result" id="result"></div></section>
</main>
<script>
const SUBMIT_URL=<?= json_encode(base_url('belajar/matematika/submit')); ?>, RUN_TOKEN=<?= json_encode($run_token); ?>, TOTAL=<?= (int) $total; ?>;
let question=<?= json_encode($question, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>, position=1, locked=false, previousAnswer='';
const $=id=>document.getElementById(id);
function esc(value){const e=document.createElement('span');e.textContent=value==null?'':value;return e.innerHTML}
function renderQuestion(){locked=false;$('board').classList.remove('loading');$('feedback').className='feedback';$('feedback').innerHTML='';$('counter').textContent=position+' / '+TOTAL;$('progress').style.width=((position/TOTAL)*100)+'%';$('prompt').textContent=question.prompt;$('hintOneText').textContent=question.hint||'Belum ada petunjuk tambahan.';$('hintTwoText').textContent=question.hint_deeper||'Coba pecah soalnya menjadi langkah kecil.';$('hintOneText').className='hint';$('hintTwoText').className='hint';$('options').innerHTML=Object.entries(question.options||{}).map(([key,value])=>`<button class="option" data-answer="${esc(key)}"><span class="letter">${esc(key)}</span><span>${esc(value)}</span></button>`).join('');document.querySelectorAll('.option').forEach(btn=>btn.addEventListener('click',()=>answer(btn.dataset.answer,btn)))}
function answer(value,button){if(locked)return;locked=true;previousAnswer=value;$('board').classList.add('loading');document.querySelectorAll('.option').forEach(b=>b.disabled=true);fetch(SUBMIT_URL,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams({run_token:RUN_TOKEN,question_id:question.id,answer:value})}).then(r=>r.json()).then(data=>{if(!data.ok)throw new Error(data.message||'Jawaban tidak dapat diproses.');showAnswer(data,button)}).catch(err=>{locked=false;$('board').classList.remove('loading');document.querySelectorAll('.option').forEach(b=>b.disabled=false);alert(err.message||'Terjadi gangguan. Silakan coba lagi.');});}
function showAnswer(data,button){$('board').classList.remove('loading');document.querySelectorAll('.option').forEach(b=>{if(b.dataset.answer===data.correct_option)b.classList.add('correct');if(b===button&&!data.correct)b.classList.add('wrong')});if(data.correct){document.body.classList.add('celebrate');setTimeout(()=>document.body.classList.remove('celebrate'),900)}const feedback=$('feedback');feedback.className='feedback show '+(data.correct?'good':'bad');feedback.innerHTML=`<h3>${data.correct?'✓ Tepat sekali!':'Belum tepat, tidak apa-apa.'}</h3><p>${esc(data.explanation)}</p><p class="tip"><i class="ti ti-bulb"></i> <b>Tips:</b> ${esc(data.tip)}</p>${data.finished?'': '<button class="next" id="nextBtn">Soal berikutnya <i class="ti ti-arrow-right"></i></button>'}`;if(data.finished){setTimeout(()=>showResult(data),850)}else{$('nextBtn').addEventListener('click',()=>{question=data.next_question;position=data.position;renderQuestion()})}}
function showResult(data){$('gamePanel').style.display='none';const result=$('result');result.className='result show';const passed=data.passed;result.innerHTML=`<div class="result-badge">${passed?'🏁':'💪'}</div><h2>${passed?'Pos berhasil dituntaskan!':'Hampir sampai!'}</h2><p>${passed?'Kamu sudah membuka pos berikutnya. Pembahasan pada tiap soal adalah bekal terbaik untuk terus naik level.':'Kamu perlu minimal '+data.passing_correct+' jawaban benar. Baca ulang pembahasan dan coba lagi—progres terbaikmu tetap tersimpan.'}</p><div class="score"><div><b>${data.correct_count}/${TOTAL}</b><small>Jawaban benar</small></div><div><b>${data.score}%</b><small>Skor</small></div><div><b>${data.points_earned? '+'+data.points_earned:'—'}</b><small>Poin baru</small></div></div><a href="${esc(data.next_url)}">Kembali ke peta level <i class="ti ti-map-2"></i></a>`;}
$('hintOne').addEventListener('click',()=>$('hintOneText').classList.toggle('show'));$('hintTwo').addEventListener('click',()=>$('hintTwoText').classList.toggle('show'));renderQuestion();
</script></body></html>
